content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  background-color: #0b0f19;
  color: #f3f4f6;
  overflow: hidden;
}

.app-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100vw;
  position: relative;
  background: radial-gradient(circle at center, #1b2737 0%, #090a0f 100%);
}

.header {
  height: 60px;
  background: rgba(11, 15, 25, 0.85);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  z-index: 10;
}

.header h1 {
  font-size: 1.25rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  color: #ffffff;
}

.main-layout {
  display: flex;
  flex: 1;
  position: relative;
  overflow: hidden;
}

.canvas-container {
  flex: 1;
  height: 100%;
  width: 100%;
  position: absolute;
  top: 0;
  left: 0;
  z-index: 1;
}

.control-panel {
  position: absolute;
  top: 20px;
  right: 20px;
  width: 320px;
  background: rgba(17, 24, 39, 0.85);
  backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 12px;
  padding: 20px;
  z-index: 10;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.slider-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.slider-group label {
  font-size: 0.85rem;
  color: #9ca3af;
  display: flex;
  justify-content: space-between;
}

.slider-group input[type="range"] {
  width: 100%;
  accent-color: #3b82f6;
  cursor: pointer;
}

.btn {
  background: #3b82f6;
  color: #ffffff;
  border: none;
  border-radius: 6px;
  padding: 10px 16px;
  font-size: 0.9rem;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.btn:hover {
  background: #2563eb;
}

.btn:active {
  transform: scale(0.98);
}

.planet-info-card {
  background: rgba(31, 41, 55, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 8px;
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.planet-info-card h3 {
  font-size: 1.1rem;
  font-weight: 600;
  color: #ffffff;
  display: flex;
  align-items: center;
  gap: 8px;
}

.planet-info-card p {
  font-size: 0.85rem;
  color: #d1d5db;
  line-height: 1.4;
}

@media (max-width: 768px) {
  .control-panel {
    top: auto;
    bottom: 20px;
    left: 20px;
    right: 20px;
    width: auto;
    max-height: 50vh;
    overflow-y: auto;
  }
}

export interface Planet {
  id: string;
  name: string;
  radius: number;
  distance: number;
  speed: number;
  color: string;
  description: string;
  size: number;
}

export interface SimulationSettings {
  speedMultiplier: number;
  isPaused: boolean;
  selectedPlanetId: string | null;
}

import { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { planets } from './planetData';
import { SimulationSettings } from './types';
import './index.css';

interface PlanetViewerProps {
  settings: SimulationSettings;
  onSelectPlanet: (id: string | null) => void;
}

export default function PlanetViewer({ settings, onSelectPlanet }: PlanetViewerProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const settingsRef = useRef(settings);
  settingsRef.current = settings;

  useEffect(() => {
    if (!containerRef.current) return;

    const container = containerRef.current;
    const width = container.clientWidth;
    const height = container.clientHeight;

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x050508);

    // Camera
    const camera = new THREE.PerspectiveCamera(60, width / height, 0.1, 1000);
    camera.position.set(0, 40, 60);
    camera.lookAt(0, 0, 0);

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    container.appendChild(renderer.domElement);

    // Lights
    const ambientLight = new THREE.AmbientLight(0x333333);
    scene.add(ambientLight);

    const pointLight = new THREE.PointLight(0xffffff, 2, 300);
    pointLight.position.set(0, 0, 0);
    scene.add(pointLight);

    // Planet Meshes & Orbits
    const planetMeshes: { [key: string]: THREE.Mesh } = {};
    const planetAngles: { [key: string]: number } = {};

    planets.forEach((planet) => {
      planetAngles[planet.id] = Math.random() * Math.PI * 2;

      if (planet.distance > 0) {
        const orbitGeometry = new THREE.RingGeometry(planet.distance - 0.05, planet.distance + 0.05, 64);
        const orbitMaterial = new THREE.MeshBasicMaterial({
          color: 0xffffff,
          side: THREE.DoubleSide,
          transparent: true,
          opacity: 0.15,
        });
        const orbitMesh = new THREE.Mesh(orbitGeometry, orbitMaterial);
        orbitMesh.rotation.x = Math.PI / 2;
        scene.add(orbitMesh);
      }

      const geometry = new THREE.SphereGeometry(planet.size, 32, 32);
      const material = new THREE.MeshStandardMaterial({
        color: planet.color,
        emissive: planet.id === 'sun' ? planet.color : 0x000000,
        emissiveIntensity: planet.id === 'sun' ? 1 : 0,
        roughness: 0.8,
        metalness: 0.2,
      });
      const mesh = new THREE.Mesh(geometry, material);
      mesh.userData = { id: planet.id };
      scene.add(mesh);
      planetMeshes[planet.id] = mesh;
    });

    // Raycaster for clicking planets
    const raycaster = new THREE.Raycaster();
    const mouse = new THREE.Vector2();

    const handlePointerDown = (event: PointerEvent) => {
      const rect = container.getBoundingClientRect();
      mouse.x = ((event.clientX - rect.left) / container.clientWidth) * 2 - 1;
      mouse.y = -((event.clientY - rect.top) / container.clientHeight) * 2 + 1;

      raycaster.setFromCamera(mouse, camera);
      const intersects = raycaster.intersectObjects(scene.children);

      for (const intersect of intersects) {
        if (intersect.object && intersect.object.userData && intersect.object.userData.id) {
          onSelectPlanet(intersect.object.userData.id);
          return;
        }
      }
      onSelectPlanet(null);
    };

    container.addEventListener('pointerdown', handlePointerDown);

    // Animation Loop
    let animationFrameId: number;
    const clock = new THREE.Clock();

    const animate = () => {
      animationFrameId = requestAnimationFrame(animate);
      const delta = clock.getDelta();
      const currentSettings = settingsRef.current;

      if (!currentSettings.isPaused) {
        planets.forEach((planet) => {
          const mesh = planetMeshes[planet.id];
          if (!mesh) return;

          if (planet.distance === 0) {
            mesh.rotation.y += 0.001 * currentSettings.speedMultiplier;
          } else {
            planetAngles[planet.id] += planet.speed * currentSettings.speedMultiplier * delta * 10;
            const angle = planetAngles[planet.id];
            const x = Math.cos(angle) * planet.distance;
            const z = Math.sin(angle) * planet.distance;
            mesh.position.set(x, 0, z);
            mesh.rotation.y += 0.01 * currentSettings.speedMultiplier;
          }
        });
      }

      if (currentSettings.selectedPlanetId) {
        const selectedMesh = planetMeshes[currentSettings.selectedPlanetId];
        if (selectedMesh && currentSettings.selectedPlanetId !== 'sun') {
          const targetPos = selectedMesh.position;
          camera.position.x += (targetPos.x + 5 - camera.position.x) * 0.05;
          camera.position.z += (targetPos.z + 10 - camera.position.z) * 0.05;
          camera.position.y += (targetPos.y + 5 - camera.position.y) * 0.05;
          camera.lookAt(targetPos);
        } else if (currentSettings.selectedPlanetId === 'sun') {
          camera.position.x += (0 - camera.position.x) * 0.05;
          camera.position.z += (30 - camera.position.z) * 0.05;
          camera.position.y += (15 - camera.position.y) * 0.05;
          camera.lookAt(0, 0, 0);
        }
      }

      renderer.render(scene, camera);
    };

    animate();

    const handleResize = () => {
      if (!container) return;
      const w = container.clientWidth;
      const h = container.clientHeight;
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
    };

    window.addEventListener('resize', handleResize);

    return () => {
      cancelAnimationFrame(animationFrameId);
      window.removeEventListener('resize', handleResize);
      container.removeEventListener('pointerdown', handlePointerDown);
      if (renderer.domElement && container.contains(renderer.domElement)) {
        container.removeChild(renderer.domElement);
      }
      renderer.dispose();
    };
  }, []);

  return <div className="canvas-container" ref={containerRef} />;
}

import { planets } from './planetData';
import { SimulationSettings } from './types';
import './index.css';

interface ControlPanelProps {
  settings: SimulationSettings;
  onUpdateSettings: (newSettings: Partial<SimulationSettings>) => void;
  onSelectPlanet: (id: string | null) => void;
}

export default function ControlPanel({ settings, onUpdateSettings, onSelectPlanet }: ControlPanelProps) {
  const selectedPlanet = planets.find((p) => p.id === settings.selectedPlanetId);

  return (
    <div className="control-panel">
      <div className="slider-group">
        <label>
          <span>シミュレーション速度</span>
          <span>{settings.speedMultiplier.toFixed(1)}x</span>
        </label>
        <input
          type="range"
          min="0.1"
          max="5"
          step="0.1"
          value={settings.speedMultiplier}
          onChange={(e) => onUpdateSettings({ speedMultiplier: parseFloat(e.target.value) })}
        />
      </div>

      <button
        className="btn"
        onClick={() => onUpdateSettings({ isPaused: !settings.isPaused })}
      >
        {settings.isPaused ? '再生する' : '一時停止'}
      </button>

      {selectedPlanet ? (
        <div className="planet-info-card">
          <h3>
            <span
              style={{
                display: 'inline-block',
                width: '12px',
                height: '12px',
                borderRadius: '50%',
                backgroundColor: selectedPlanet.color,
              }}
            />
            {selectedPlanet.name}
          </h3>
          <p>{selectedPlanet.description}</p>
          <button
            className="btn"
            style={{ marginTop: '8px', background: '#4b5563', fontSize: '0.8rem', padding: '6px 12px' }}
            onClick={() => onSelectPlanet(null)}
          >
            選択解除
          </button>
        </div>
      ) : (
        <div className="planet-info-card">
          <h3>情報</h3>
          <p>惑星をクリックするか、太陽系を自由に観察してみましょう。</p>
        </div>
      )}
    </div>
  );
}

import { useState } from 'react';
import PlanetViewer from './PlanetViewer';
import ControlPanel from './ControlPanel';
import { SimulationSettings } from './types';
import './index.css';

export default function App() {
  const [settings, setSettings] = useState<SimulationSettings>({
    speedMultiplier: 1.0,
    isPaused: false,
    selectedPlanetId: null,
  });

  const handleUpdateSettings = (newSettings: Partial<SimulationSettings>) => {
    setSettings((prev) => ({ ...prev, ...newSettings }));
  };

  const handleSelectPlanet = (id: string | null) => {
    setSettings((prev) => ({ ...prev, selectedPlanetId: id }));
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1>3D太陽系シミュレーション</h1>
      </header>
      <div className="main-layout">
        <div className="canvas-container">
          <PlanetViewer settings={settings} onSelectPlanet={handleSelectPlanet} />
        </div>
        <ControlPanel
          settings={settings}
          onUpdateSettings={handleUpdateSettings}
          onSelectPlanet={handleSelectPlanet}
        />
      </div>
    </div>
  );
}
